const { execFileSync } = await import("child_process");
const { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const dir = mkdtempSync(join(tmpdir(), "koala-aux-sync-fixture-"));
try {
  mkdirSync(join(dir, "packages", "main", "src"), { recursive: true });
  mkdirSync(join(dir, "docs", "metadata"), { recursive: true });
  mkdirSync(join(dir, "docs", "requirements"), { recursive: true });
  writeFileSync(join(dir, "koala.config.json"), JSON.stringify({ scanRoot: "packages/main", rootDir: "src", outDir: "packages/main/dist", testsDir: "packages/main/tests", fixturesDir: "packages/main/tests/fixtures", storyDir: "docs/story/actives", requirementsDir: "docs/requirements", storyPrefix: "B" }, null, 2));
  writeFileSync(join(dir, "packages", "main", "src", "sample.ts"), "/**\n * @task B-sync\n * @checklist CHK-001\n * @title fail-fast extract fixture\n * @type feature\n * @priority high\n * @description\n *   source annotation should replace stale metadata during extract.\n * @changes\n *   - [CHK-001] extract reads source annotations first\n */\nexport function sample() { return 'ok'; }\n");
  writeFileSync(join(dir, "docs", "metadata", "task.json"), JSON.stringify({ version: 1, updatedAt: new Date().toISOString(), tasks: [{ key: "src/old.ts", task: "STALE-001", title: "stale" }] }, null, 2));
  writeFileSync(join(dir, "docs", "metadata", "flow.json"), JSON.stringify({ version: 1, updatedAt: new Date().toISOString(), flows: [] }, null, 2));
  execFileSync("node", [$root + "/bin/koala-codex.js", "--root", dir, "aux_sync", "--direction=extract"], { cwd: $root, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"] });
  const store = JSON.parse(readFileSync(join(dir, "docs", "metadata", "task.json"), "utf8"));
  return { replacedStale: store.tasks.length === 1 && store.tasks[0].task === "B-sync" };
} finally { rmSync(dir, { recursive: true, force: true }); }

const { scanSourceAnnotations } = await import($root + "/packages/main/dist/tasks/extract.js");
