const { execFileSync } = await import("child_process");
const { mkdtempSync, writeFileSync, rmSync } = await import("fs");
const { tmpdir } = await import("os");
const { join } = await import("path");
const dir = mkdtempSync(join(tmpdir(), "koala-health-report-"));
const file = join(dir, "health.jsonl");
try {
  writeFileSync(file, JSON.stringify({ schemaVersion: 1, timestamp: new Date().toISOString(), category: "persist:testEvidence", error: "disk full", context: { storyId: "B-9dae" } }) + "\n");
  const raw = execFileSync("node", [$root + "/packages/main/dist/cli.js", "--root", $root, "doctor", JSON.stringify({ format: "json", limit: 20 })], { cwd: $root, encoding: "utf8", stdio: ["pipe", "pipe", "pipe"], env: { ...process.env, KOALA_HEALTH_PATH: file } });
  const json = JSON.parse(raw.slice(raw.indexOf("{")));
  return { categoryVisible: (json.byCategory?.["persist:testEvidence"] || 0) >= 1, recentVisible: json.recent.some((row) => row.category === "persist:testEvidence") };
} finally { rmSync(dir, { recursive: true, force: true }); }

const { readFileSync } = await import("fs");
const text = readFileSync($root + "/packages/main/src/handlers/test-story.ts", "utf8");
return { evidenceReported: text.includes("persist:testEvidence"), runsReported: text.includes("persist:testRuns") };
